// =====================================================================
//  Stellarium Unhinged — app.js
//  STEP 1: a calm night sky full of constellations.
//  STEP 2: Orion breakdances (toprock, windmill, headspin).
//  STEP 3: every constellation gets a personality + tappable info cards.
//  STEP 4: BATTLE: all four matchups fight at once, right there in the sky.
//  STEP 5: rave mode, real mode and screenshot sharing.
//  EXTRA:  mythological figures drawn around the stars (they move too).
// =====================================================================

// ---------- Canvas setup ----------
const canvas = document.getElementById('sky');
const ctx = canvas.getContext('2d');

let W = 0;            // canvas width in CSS pixels
let H = 0;            // canvas height in CSS pixels
let unit = 0;         // one "constellation unit" in pixels (scales with screen size)
let portrait = true;  // phone held upright? (changes the layout)
let toolbarH = 44;    // height of the button bar (measured on resize)

// Users who ask their OS for less motion get gentler animation.
const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const BASE_SPEED = reduceMotion ? 0.5 : 1;
let speed = BASE_SPEED;   // dance speed; rave mode turns it up

// ---------- Small helpers ----------
const clamp01 = v => Math.max(0, Math.min(1, v));
const ease = t => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2); // smooth start + stop
const lerp = (a, b, t) => a + (b - a) * t;
const pick = list => list[Math.floor(Math.random() * list.length)];
const fillIn = (text, vars) => text.replace(/\{(\w)\}/g, (_, key) => vars[key]);

// Rotate a point around an origin by `angle` radians.
function rotate(p, angle, origin) {
  const cos = Math.cos(angle), sin = Math.sin(angle);
  const dx = p.x - origin.x, dy = p.y - origin.y;
  return { x: origin.x + dx * cos - dy * sin, y: origin.y + dx * sin + dy * cos };
}

