const byId = Object.fromEntries(CONSTELLATIONS.map(c => [c.id, c]));

// ---------- The four fights: [left fighter, right fighter] ----------
// Each pair sits side by side in the sky, so they can fight where they are.
const FIGHTS = [
  ['cassiopeia', 'ursa'],
  ['hercules', 'draco'],
  ['orion', 'scorpius'],
  ['perseus', 'cetus'],
];
// Remember each fighter's pair number and side (0 = left, 1 = right)
FIGHTS.forEach((pair, i) => pair.forEach((id, side) => { byId[id].pair = i; byId[id].side = side; }));

// ---------- Background stars ----------
// Positions are stored as fractions (0–1) so they survive screen resizes.
const BG_STARS = [];
function makeBackgroundStars(count) {
  for (let i = 0; i < count; i++) {
    BG_STARS.push({
      x: Math.random(),
      y: Math.random() * 0.92,            // keep them above the horizon
      r: Math.random() * 1.2 + 0.2,       // radius in px
      phase: Math.random() * Math.PI * 2, // where in the twinkle cycle it starts
      speed: Math.random() * 2 + 0.5,     // how fast it twinkles
    });
  }
}

// ---------- Resize: keep the canvas sharp on every screen ----------
function resize() {
  const dpr = window.devicePixelRatio || 1;
  W = window.innerWidth;
  H = window.innerHeight;
  canvas.width = W * dpr;            // real pixels
  canvas.height = H * dpr;
  canvas.style.width = W + 'px';     // CSS pixels
  canvas.style.height = H + 'px';
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0); // draw in CSS pixels from now on
  artCanvas.width = canvas.width;          // the hidden canvas for figures matches the sky
  artCanvas.height = canvas.height;
  actx.setTransform(dpr, 0, 0, dpr, 0, 0);
  portrait = W < H;
  unit = portrait ? Math.min(W * 0.15, H * 0.07) : Math.min(W * 0.055, H * 0.11);
  toolbarH = document.querySelector('.toolbar').offsetHeight;   // buttons may wrap onto 2 rows on phones
  document.documentElement.style.setProperty('--toolbar-h', toolbarH + 'px');
}

// ---------- Layout: where each constellation sits ----------
// Phones (portrait): the four pairs are stacked in rows.
// Laptops (landscape): the four pairs sit in a 2 × 2 grid.
function slotPosition(pairIndex, side) {
  if (portrait) {
    return { x: (side === 0 ? 0.27 : 0.73) * W, y: (0.21 + pairIndex * 0.175) * H };
  }
  const col = pairIndex % 2, row = Math.floor(pairIndex / 2);
  const slotX = 0.25 + 0.5 * col;
  return { x: (slotX + (side === 0 ? -0.13 : 0.13)) * W, y: (0.30 + 0.34 * row) * H };
}

// Returns pixel position, size and visibility for a constellation right now.
function layoutOf(c) {
  const pos = slotPosition(c.pair, c.side);
  return { x: pos.x, y: pos.y, scale: 1, alpha: 1 };
}

// =====================================================================
//  PERSONALITIES
//  Each takes the resting stars + the time and returns a "pose"
//  (star positions for this exact moment) plus a caption.
// =====================================================================

// ORION BREAKDANCES. He cycles through three moves, 4 seconds each.
function orionDance(c, time) {
  const sec = time / 1000 * speed;
  const beat = sec * 2 * Math.PI;           // one full wave per second
  const move = Math.floor(sec / 4) % 3;     // 0, 1, 2, 0, 1, 2 ...
  const belt = c.stars[4];                  // he spins around his belt (Alnilam)

  if (move === 0) {                         // TOPROCK: bounce, shimmy, kick
    const bounce = -Math.abs(Math.sin(beat)) * 0.22;
    const pose = c.stars.map((s, i) => {
      let x = s.x, y = s.y + bounce;
      if (i === 1 || i === 2) y -= Math.max(0, Math.sin(beat + i * Math.PI)) * 0.35; // arms up, one at a time
      if (i === 6) x -= Math.max(0, Math.sin(beat)) * 0.3;  // left knee kicks
      if (i === 7) x += Math.max(0, -Math.sin(beat)) * 0.3; // right knee kicks
      if (i === 0) x += Math.sin(beat * 2) * 0.12;          // head bob
      return { x, y };
    });
    return { pose, caption: 'TOPROCK' };
  }
  if (move === 1) {                         // WINDMILL: spins like a propeller
    const angle = sec * Math.PI * 1.5;
    return { pose: c.stars.map(s => rotate(s, angle, belt)), caption: 'WINDMILL' };
  }
  // HEADSPIN: flip upside down, then squash left-right to fake a 3D spin
  const spin = Math.cos(sec * 10);
  const pose = c.stars.map(s => {
    const flipped = rotate(s, Math.PI, belt);
    return { x: belt.x + (flipped.x - belt.x) * spin, y: flipped.y - 0.4 };
  });
  return { pose, caption: 'HEADSPIN' };
}

// URSA MAJOR drifts lazily, gets sleepy, tips over and snores. 14-second cycle.
// In a battle she's woken up (grumpily) to fight Cassiopeia.
function ursaSleep(c, time) {
  const sec = time / 1000 * speed;
  const cycle = sec % 14;
  let sleep = clamp01((cycle - 5) / 2);         // dozes off between 5s and 7s
  if (cycle > 12) sleep = 1 - (cycle - 12) / 2; // wakes up between 12s and 14s
  if (battle.active) sleep = 0;

  const driftX = Math.sin(sec * 0.35) * 0.35;  // slow side-to-side float
  const driftY = Math.sin(sec * 0.6) * 0.12;
  const breathe = 1 + Math.sin(sec * 1.5) * 0.06 * sleep; // snoring = gentle grow/shrink

  const pose = c.stars.map((s, i) => {
    let p = rotate(s, sleep * 0.45, { x: 0, y: 0 });       // tips over when asleep
    p = { x: p.x * breathe + driftX * (1 - sleep * 0.7), y: p.y * breathe + driftY + sleep * 0.15 };
    if (i >= 4) p.y += sleep * (i - 3) * 0.08;             // the tail droops
    return p;
  });

  let caption = sleep > 0.8 ? 'DO NOT DISTURB' : sleep > 0.05 ? 'YAWN…' : 'DRIFTING…';

  const draw = (pts, scale) => {               // floating "Z"s while asleep
    if (sleep < 0.3) return;
    const head = pts[0];
    ctx.fillStyle = '#bcd4ff';
    for (let k = 0; k < 3; k++) {
      const t = (sec * 0.6 + k / 3) % 1;      // each Z rises, fades, restarts
      ctx.globalAlpha = (1 - t) * sleep;
      ctx.font = `800 ${unit * scale * (0.14 + t * 0.18)}px "Bricolage Grotesque", sans-serif`;
      ctx.fillText('Z', head.x + unit * scale * (0.25 + t * 0.4), head.y - unit * scale * (0.15 + t * 0.7));
    }
    ctx.globalAlpha = 1;
  };
  return { pose, caption, draw, still: sleep > 0.3 };
}

// CASSIOPEIA can't decide if she's a W or an M. Flips every few seconds.
function cassiopeiaFlip(c, time) {
  const sec = time / 1000 * speed;
  const cycle = sec % 6;
  let flip; // 1 = W, -1 = M, in between = mid-flip
  if (cycle < 2) flip = 1;
  else if (cycle < 3) flip = Math.cos(ease(cycle - 2) * Math.PI);
  else if (cycle < 5) flip = -1;
  else flip = -Math.cos(ease(cycle - 5) * Math.PI);

  const shaking = Math.abs(flip) < 1;  // jitter while flipping
  const shimmy = Math.sin(sec * 12) * 0.08;  // hip shimmy while she holds a letter
  const pose = c.stars.map((s, i) => ({
    x: s.x + (shaking ? Math.sin(sec * 40 + i) * 0.06 : shimmy * s.y),
    y: s.y * flip,                      // multiply y by -1 to turn W into M
  }));
  const caption = flip > 0.3 ? "IT'S A W" : flip < -0.3 ? 'NO WAIT, M' : '???';
  return { pose, caption };
}

// SCORPIUS chases Orion, snaps his claws, then retreats. 8-second cycle.
// In a battle he stops chasing (the fight brings Orion to him).
function scorpiusChase(c, time) {
  const sec = time / 1000 * speed;
  const me = layoutOf(c), orion = layoutOf(byId.orion);
  const gapX = (orion.x - me.x) / unit + 1.9;   // walk until just right of Orion
  const gapY = (orion.y - me.y) / unit;

  const cycle = sec % 8;
  let p, caption;              // p: 0 = at home, 1 = next to Orion
  if (cycle < 3)      { p = ease(cycle / 3);           caption = 'GET BACK HERE'; }
  else if (cycle < 5) { p = 1;                         caption = 'SNIP SNIP'; }
  else                { p = 1 - ease((cycle - 5) / 3); caption = 'TACTICAL RETREAT'; }
  if (battle.active) p = 0;

  const walking = !battle.active && (cycle < 3 || cycle >= 5);
  const snap = Math.sin(sec * 20);              // claws open/close
  const jab = Math.max(0, Math.sin(sec * 6));   // stinger jabs

  const pose = c.stars.map((s, i) => {
    let x = s.x + gapX * p, y = s.y + gapY * p;
    if (walking) y += Math.sin(sec * 14 + i) * 0.04; // scuttling
    if (!walking && i === 0) y -= snap * 0.12;       // upper claw
    if (!walking && i === 2) y += snap * 0.12;       // lower claw
    if (i >= 9) x -= jab * 0.25;                     // stinger
    return { x, y };
  });
  return { pose, caption };
}

// Shared timing for dance routines: switch moves every 4 seconds.
// Returns which move is playing and a "beat" angle (one full wave per second).
function danceClock(time, moves) {
  const sec = time / 1000 * speed;
  return { sec, beat: sec * 2 * Math.PI, move: Math.floor(sec / 4) % moves };
}

// PERSEUS dances: the robot, voguing with Medusa's head, then the moonwalk.
function perseusDance(c, time) {
  const { sec, beat, move } = danceClock(time + 1300, 3); // offset so he's not in sync with Orion
  const hip = c.stars[2];                                  // Mirfak, his middle

  if (move === 0) {                         // THE ROBOT: stiff, snapping steps
    const step = Math.round(Math.sin(beat) * 2) / 2;       // jumps between -1, -0.5, 0, 0.5, 1
    const pose = c.stars.map((s, i) => {
      if (i === 6 || i === 7) return rotate(s, step * 0.6, hip);    // arm snaps up and down
      if (i === 0 || i === 1) return rotate(s, -step * 0.25, hip);  // head ticks the other way
      return { x: s.x, y: s.y - Math.abs(step) * 0.05 };
    });
    return { pose, caption: 'THE ROBOT' };
  }
  if (move === 1) {                         // VOGUE: Medusa's head swoops around him
    const sway = Math.sin(beat * 0.5) * 0.3;
    const pose = c.stars.map((s, i) => {
      const p = rotate(s, sway, hip);
      return (i === 6 || i === 7) ? rotate(p, Math.sin(beat * 0.75) * 1.8, hip) : p;
    });
    return { pose, caption: 'VOGUE' };
  }
  // MOONWALK: glides backwards while his feet take turns stepping
  const glide = Math.sin(sec * 1.2) * 0.75;
  const pose = c.stars.map((s, i) => {
    let x = s.x + glide, y = s.y;
    if (i === 4 || i === 5) y -= Math.max(0, Math.sin(beat)) * 0.18;
    if (i === 3) y -= Math.max(0, -Math.sin(beat)) * 0.12;
    return { x, y };
  });
  return { pose, caption: 'MOONWALK' };
}

// CETUS dances: the worm, a dolphin leap, then chomping to the beat.
function cetusDance(c, time) {
  const { sec, beat, move } = danceClock(time + 2600, 3);
  const center = { x: 0, y: 0 };

  if (move === 0) {                         // THE WORM: a big wave rolls along his body
    const pose = c.stars.map(s => ({ x: s.x, y: s.y + Math.sin(beat - s.x * 3) * 0.38 }));
    return { pose, caption: 'THE WORM' };
  }
  if (move === 1) {                         // DOLPHIN LEAP: jumps in an arc and tilts
    const t = (sec % 2) / 2;                // 0 → 1 every 2 seconds
    const lift = Math.sin(t * Math.PI) * 1.0;
    const tilt = Math.cos(t * Math.PI) * 0.7;
    const pose = c.stars.map(s => {
      const p = rotate(s, -tilt, center);
      return { x: p.x, y: p.y - lift };
    });
    return { pose, caption: 'DOLPHIN LEAP' };
  }
  // CHOMP: jaws snap open and shut while his body shakes
  const open = Math.max(0, Math.sin(beat * 1.5)) * 0.2;
  const pose = c.stars.map((s, i) => {
    let x = s.x + Math.sin(beat * 4) * 0.03, y = s.y;
    if (i === 1) y -= open;                 // top of the head
    if (i === 3) y += open;                 // jaw
    if (i === 0) x -= open * 0.5;           // snout lunges
    return { x, y };
  });
  return { pose, caption: 'CHOMP CHOMP' };
}

// HERCULES dances: somersaults, jumping jacks, flexing, then the sprinkler.
function herculesDance(c, time) {
  const { sec, beat, move } = danceClock(time + 600, 4);
  const center = { x: 0, y: 0 };

  if (move === 0) {                         // SOMERSAULT: a full flip every 2 seconds
    const t = (sec % 2) / 2;                // 0 → 1 during each flip
    const spin = ease(t) * Math.PI * 2;     // one full turn
    const lift = Math.sin(t * Math.PI) * 0.7; // up in the air, then land
    const tuck = 1 - Math.sin(t * Math.PI) * 0.25; // curls into a ball mid-air
    const pose = c.stars.map(s => {
      const p = rotate({ x: s.x * tuck, y: s.y * tuck }, spin, center);
      return { x: p.x, y: p.y - lift };
    });
    return { pose, caption: 'SOMERSAULT', still: true };
  }
  if (move === 1) {                         // JUMPING JACKS: arms up and legs out, then back
    const j = (Math.sin(beat * 1.5) + 1) / 2;   // 0 = closed, 1 = open
    const pose = c.stars.map((s, i) => {
      let x = s.x, y = s.y - j * 0.25;           // hop
      if (i === 4) { x -= j * 0.2; y -= j * 0.5; } // arms
      if (i === 5) { x += j * 0.2; y -= j * 0.5; }
      if (i === 6) x -= j * 0.4;                  // legs
      if (i === 7) x += j * 0.4;
      return { x, y };
    });
    return { pose, caption: 'JUMPING JACKS' };
  }
  if (move === 2) {                         // FLEXING: chest pumps, arms curl in
    const pump = Math.max(0, Math.sin(beat * 1.25));
    const pose = c.stars.map((s, i) => {
      let x = s.x * (1 + pump * 0.3), y = s.y;
      if (i === 4 || i === 5) y += pump * 0.35;
      return { x, y };
    });
    return { pose, caption: 'FLEXING' };
  }
  // THE SPRINKLER: one arm out, body ticks side to side in little steps
  const tick = Math.round(Math.sin(beat * 0.5) * 4) / 4;
  const pose = c.stars.map((s, i) => {
    let p = rotate(s, tick * 0.5, { x: 0, y: 0.2 });
    if (i === 4) p = { x: p.x + 0.2, y: p.y + 0.5 };
    return p;
  });
  return { pose, caption: 'THE SPRINKLER' };
}

// DRACO dances: big slithers, a full-body twist, then a fire dance.
function dracoDance(c, time) {
  const { sec, beat, move } = danceClock(time + 3400, 3);
  const head = c.stars[0];

  if (move === 0) {                         // SLITHER: a wave runs from head to tail
    const pose = c.stars.map(s => ({ x: s.x, y: s.y + Math.sin(beat + s.x * 4) * 0.32 }));
    return { pose, caption: 'SLITHER' };
  }
  if (move === 1) {                         // THE TWIST: the farther from the head, the more it twists
    const twist = Math.sin(beat * 0.75) * 0.75;
    const pose = c.stars.map(s => {
      const dist = Math.hypot(s.x - head.x, s.y - head.y);
      return rotate(s, twist * dist * 0.6, head);
    });
    return { pose, caption: 'THE TWIST' };
  }
  // FIRE DANCE: head bobs to the beat and breathes little flames
  const bob = Math.sin(beat * 2) * 0.12;
  const pose = c.stars.map((s, i) => ({
    x: s.x,
    y: s.y + (i <= 3 ? bob : Math.sin(beat + s.x * 3) * 0.08),
  }));
  const draw = (pts, scale) => {
    const mouth = pts[2];
    ctx.save();
    ctx.strokeStyle = '#ffa64d';
    ctx.shadowColor = '#ff6a00';
    ctx.shadowBlur = 10;
    ctx.lineWidth = 2;
    ctx.globalAlpha *= 0.5 + 0.5 * Math.abs(Math.sin(sec * 6));
    for (let k = 0; k < 5; k++) {
      const a = Math.PI + (k - 2) * 0.15;   // flames shoot out to the left
      const len = unit * scale * (0.3 + Math.random() * 0.35);
      ctx.beginPath();
      ctx.moveTo(mouth.x, mouth.y);
      ctx.lineTo(mouth.x + Math.cos(a) * len, mouth.y + Math.sin(a) * len);
      ctx.stroke();
    }
    ctx.restore();
  };
  return { pose, caption: 'FIRE DANCE', draw };
}

// Which constellation uses which personality.
const PERSONALITIES = {
  orion: orionDance, ursa: ursaSleep, cassiopeia: cassiopeiaFlip, scorpius: scorpiusChase,
  perseus: perseusDance, cetus: cetusDance, hercules: herculesDance, draco: dracoDance,
};

function getPose(c, time) {
  if (real.on) return { pose: c.stars, caption: '' };   // real mode: perfectly still, like the real sky
  const personality = PERSONALITIES[c.id];
  const result = personality ? personality(c, time) : { pose: c.stars, caption: '' };
  if (result.still) return result;          // moves that look better without extra groove

  // Extra groove for everyone: a bounce on the beat plus a gentle side-to-side sway.
  // Each constellation gets its own offset so they don't all move in sync.
  const beat = time / 1000 * speed * 2 * Math.PI + c.id.length * 1.7;
  const bounce = -Math.abs(Math.sin(beat)) * 0.1;
  const sway = Math.sin(beat / 2) * 0.09;
  result.pose = result.pose.map(p => {
    const r = rotate(p, sway, { x: 0, y: 0 });
    return { x: r.x, y: r.y + bounce };
  });
  return result;
}

// =====================================================================
//  BATTLE MODE
//  All four fights happen at once, each pair fighting where it stands.
//  Every attack is random, so every winner is random.
// =====================================================================

// Fighter colors and signature announcer lines ({d} = the one getting hit)
const FIGHTERS = {
  orion:      { color: '#7fb2ff', signature: 'Orion swings the club! He finally caught something!' },
  scorpius:   { color: '#ff7a59', signature: 'THE STINGER! Just like in the myth! He will bring this up at every party!' },
  perseus:    { color: '#8fe3c0', signature: 'Perseus flashes the mirror shield! {d} sees their own reflection and screams!' },
  cetus:      { color: '#6ad1ff', signature: 'Cetus belly-flops! Tsunami warning for the entire Southern Hemisphere!' },
  hercules:   { color: '#ffd36b', signature: 'Hercules flexes so hard that {d} takes damage from the vibe alone!' },
  draco:      { color: '#a3f07a', signature: "Draco breathes fire! He's been saving that one since the Jurassic!" },
  cassiopeia: { color: '#ff8fd6', signature: 'Cassiopeia bonks {d} with her mirror and says "I\'m prettier than you." Devastating!' },
  ursa:       { color: '#e0b878', signature: 'Someone woke the bear! Ursa Major body-slams {d} with the full weight of the Big Dipper!' },
};

// Announcer lines. {a} attacker, {d} defender, {w} winner, {l} loser
const LINES = {
  hit: [
    "{a} lands a cosmic haymaker on {d}! That's going to leave a nebula!",
    'OH! {a} hits {d} so hard the light will arrive in 2,000 years!',
    '{d} takes one right in the right ascension!',
    '{a} with the spinning backfist! The Milky Way is ON ITS FEET!',
    '{d} is seeing stars. Well, more stars than usual.',
    '{a} goes full supernova on {d}!',
  ],
  dodge: [
    '{d} dodges! Faster than light pollution ruins a camping trip!',
    '{a} swings at empty space, which, to be fair, is most of space.',
    '{d} slips it like a planet in retrograde!',
    '{a} misses by several light-years!',
  ],
  crit: [
    'CRITICAL HIT! {a} knocks {d} into the next millennium!',
    'MASSIVE! {d} felt that one in a parallel universe!',
  ],
  ko: [
    '{l} IS DOWN! {w} WINS! Somebody call an astronomer!',
    "IT'S OVER! {w} sends {l} straight to the obituaries!",
    '{l} collapses like a dying star! {w} takes it!',
    '{l} falls out of the sky! Everybody make a wish! {w} WINS!',
  ],
};
const POW_WORDS = ['POW!', 'BONK!', 'ZAP!', 'KAPOW!', 'THWACK!', 'SPLAT!'];

// Fake obituaries for the losers
const OBITS = {
  orion:      { years: 'c. 2000 BC – Tonight', text: 'Hunter. Belt enthusiast. Survived by three belt stars, who are already arguing over his club. In lieu of flowers, please stop asking him about Scorpius.' },
  scorpius:   { years: 'Forever – Tonight', text: 'Arachnid. Professional grudge holder. Spent eternity chasing Orion and finally caught a club instead. Survived by Antares, his heart, which is still angry.' },
  perseus:    { years: 'Mythic Era – Tonight', text: 'Hero. Collector of heads. Swore the mirror shield would work this time. A memorial will be held in Andromeda, who has asked not to be contacted.' },
  cetus:      { years: 'The Deep – Tonight', text: 'Sea monster. Career menace. Once tried to eat a princess and never apologized. Donations may be made to the Ocean, which he owes money.' },
  hercules:   { years: '12 Labors – Tonight', text: 'Strongman. Completed twelve impossible labors and failed the thirteenth: not losing to a lizard. His muscles have been donated to science.' },
  draco:      { years: '4,000 BC – Tonight', text: 'Dragon. Treasure guard. Coiled around the North Pole for millennia with nothing to show for it. The treasure has already been divided among the Little Dipper.' },
  cassiopeia: { years: 'Royal Era – Tonight', text: 'Queen. Influencer. Told the sea nymphs she was prettier, which went exactly how you would expect. Her chair is now available. It has no armrests.' },
  ursa:       { years: 'Ice Age – Tonight', text: 'Great Bear. Professional napper. Was woken up for this fight and never forgave anyone. Survived by the Little Dipper, who is now in charge of pointing at the North Star.' },
};

// ---------- Battle state ----------
const battle = {
  active: false,
  blend: 0,          // 0 = sky mode, 1 = battle mode (animates between)
  phase: 'intro',    // intro -> fight -> obit
  phaseStart: 0,
  fights: [],        // one object per pair: current attack, burst effect, result
  losers: [],        // who lost, in order, for the obituary page
  line: '',          // what the announcer is saying
  lineAt: 0,
  holdUntil: 0,      // knockout lines stay up a bit longer
  lastKO: 0,
  shake: 0,          // screen shake strength
};
const fighters = {}; // health etc. for each fighter, keyed by id
const EX_MS = 1400;  // one attack takes 1.4 seconds

function resetFighters() {
  for (const pair of FIGHTS) {
    for (const id of pair) fighters[id] = { hp: 100, shownHp: 100, flash: 0, koStart: null, winner: false };
  }
}

function startBattle() {
  const now = performance.now();
  if (real.on) setReal(false, now);
  battle.active = true;
  battle.phase = 'intro';
  battle.phaseStart = now;
  battle.losers = [];
  battle.holdUntil = 0;
  battle.fights = FIGHTS.map((pair, i) => ({
    pair, ex: null, burst: null, over: false,
    nextAt: now + 2200 + i * 350,  // stagger the fights so they don't move in sync
  }));
  resetFighters();
  battle.line = 'Four fights. One sky. Winners are random. The crowd of 400 billion stars goes wild!';
  battle.lineAt = now;
  sfx('bell');
  hideInfo();
  obitCard.hidden = true;
  updateModeUI();
}

function stopBattle() {
  battle.active = false;
  obitCard.hidden = true;
  resetFighters();           // knocked-out constellations come back
  updateModeUI();
}

// The announcer can only say one thing at a time. Normal lines wait their turn;
// knockout lines always interrupt.
function say(text, now, important = false) {
  if (important || (now > battle.holdUntil && now - battle.lineAt > 1500)) {
    battle.line = text;
    battle.lineAt = now;
    if (important) battle.holdUntil = now + 2200;
  }
}

// ---------- Fight logic (runs every frame) ----------
function updateBattle(now) {
  for (const id in fighters) {
    const f = fighters[id];
    f.shownHp += (f.hp - f.shownHp) * 0.08;   // health bar slides down smoothly
    f.flash = Math.max(0, f.flash - 0.05);
  }
  battle.shake *= 0.9;

  if (battle.phase === 'intro' && now - battle.phaseStart > 2000) battle.phase = 'fight';
  if (battle.phase !== 'fight') return;

  for (const fight of battle.fights) {
    if (fight.over) continue;
    const ex = fight.ex;
    if (ex && !ex.resolved && now - ex.start > EX_MS * 0.25) resolveExchange(fight, now); // moment of impact
    if (!fight.over && now >= fight.nextAt) {
      newExchange(fight, now);
      fight.nextAt = now + EX_MS + Math.random() * 500;
    }
  }

  if (battle.fights.every(f => f.over) && now - battle.lastKO > 2800) {
    battle.phase = 'obit';
    showObituaries();
  }
}

// Decide who attacks and whether it lands. This randomness makes winners random.
function newExchange(fight, now) {
  const attacker = Math.random() < 0.5 ? 0 : 1;
  fight.ex = {
    attacker, defender: 1 - attacker,
    dodge: Math.random() < 0.28,   // 28% chance to dodge
    crit: Math.random() < 0.12,    // 12% chance of a critical hit
    start: now, resolved: false,
  };
}

// The hit connects (or misses): apply damage, effects and commentary
function resolveExchange(fight, now) {
  const ex = fight.ex;
  ex.resolved = true;
  const aId = fight.pair[ex.attacker], dId = fight.pair[ex.defender];
  const A = fighters[aId], D = fighters[dId];
  const vars = { a: byId[aId].name, d: byId[dId].name };

  if (ex.dodge) {
    fight.burst = { word: 'WHIFF!', id: dId, start: now };
    reactDodge(aId, dId, now);
    say(fillIn(pick(LINES.dodge), vars), now);
    return;
  }

  let damage = 10 + Math.random() * 16;
  if (ex.crit) damage *= 1.8;
  D.hp = Math.max(0, D.hp - damage);
  D.flash = 1;
  battle.shake = Math.max(battle.shake, ex.crit ? 1.4 : 0.7);
  fight.burst = { word: ex.crit ? 'CRITICAL!' : pick(POW_WORDS), id: dId, start: now };
  reactHit(aId, dId, ex.crit, now);       // grunts, screams and taunts

  if (ex.crit) say(fillIn(pick(LINES.crit), vars), now);
  else if (Math.random() < 0.35) say(fillIn(FIGHTERS[aId].signature, vars), now);
  else say(fillIn(pick(LINES.hit), vars), now);

  if (D.hp <= 0) {                       // knockout!
    fight.over = true;
    D.koStart = now;
    A.winner = true;
    battle.lastKO = now;
    battle.losers.push({ loser: dId, winner: aId });
    reactKO(aId, dId, now);
    say(fillIn(pick(LINES.ko), { w: vars.a, l: vars.d }), now, true);
  }
}

// How a fighter moves right now: lunges, dodges, knockbacks, falling when KO'd.
// Returns a pixel offset, a spin angle, an opacity and a flash amount.
function battleOffset(c, now) {
  const st = fighters[c.id];
  const fight = battle.fights[c.pair];
  const dir = c.side === 0 ? 1 : -1;          // left fighter moves right, right fighter moves left
  let lunge = 0, jump = 0, knock = 0;

  const ex = fight && fight.ex;
  if (ex) {
    const p = (now - ex.start) / EX_MS;        // 0 → 1 over one attack
    if (c.side === ex.attacker) {
      // lunge in (0–25%), hold (25–40%), step back (40–70%), rest
      lunge = p < 0.25 ? ease(p / 0.25) : p < 0.4 ? 1 : p < 0.7 ? 1 - ease((p - 0.4) / 0.3) : 0;
    } else {
      if (ex.dodge && p > 0.1 && p < 0.5) jump = Math.sin((p - 0.1) / 0.4 * Math.PI);    // hop away
      if (!ex.dodge && p > 0.25 && p < 0.65) knock = Math.sin((p - 0.25) / 0.4 * Math.PI); // knocked back
    }
  }

  // Lunge far enough to reach the opponent, wherever they are on screen
  const other = layoutOf(byId[FIGHTS[c.pair][1 - c.side]]);
  const gap = Math.abs(other.x - layoutOf(c).x) / unit;
  const reach = Math.max(0.5, gap - 2.2);

  const ko = st.koStart === null ? 0 : clamp01((now - st.koStart) / 1600);
  const hop = st.winner ? Math.abs(Math.sin(now / 160)) * 0.2 : 0;

  return {
    dx: dir * (lunge * reach - knock * 0.4 - jump * 0.3) * unit,
    dy: -(jump * 0.6 + hop) * unit + ko * ko * H * 0.8,  // KO: falls out of the sky
    rot: -dir * ko * Math.PI * 2.5,                       // ...tumbling
    alpha: 1 - ko,
    flash: st.flash,
    ko,
  };
}

// =====================================================================
//  CONSTELLATION ART: mythological figures behind the stars
//  The figures are engravings from "Urania's Mirror" (1824, public domain),
//  cut out and turned silver (see FIGURES at the bottom of the file).
//
//  Every figure is built ONLY from the constellation's current star
//  positions (midpoints, extensions past a star, sideways offsets).
//  So when the stars dance, flip, sleep or fight, the figure follows.
//
//  How a figure is painted, on a hidden canvas:
//    1. smooth shapes (curved limbs, rounded bodies), outline first, then fill
//    2. shading: light from the top-left, shadow to the bottom-right
//    3. fine engraving-style hatching in the shadows, like an old star atlas
//    4. detail lines (faces, folds, fur, scales)
//  Then it's copied onto the sky semi-transparent, so stars show through.
// =====================================================================

let showArt = true;                 // toggled by the "Figures" button
const ART_OPACITY = 0.45;           // how see-through the figures are (0–1)
const artCanvas = document.createElement('canvas');  // hidden drawing surface
const actx = artCanvas.getContext('2d');

// ---------- Atlas engravings: stretch each picture to follow its stars ----------
// Every frame we find the transform (move + rotate + scale + stretch + flip) that best carries
// the constellation's resting stars onto where they are drawn right now. Applying that same
// transform to the engraving makes it dance, flip and fall with its stars.
// The fit is gently pulled toward a plain rotate-and-scale, so a constellation whose stars lie
// almost in a line (like Perseus) can't squash its picture flat.
function fitAffine(src, dst) {
  const n = src.length;
  let rx = 0, ry = 0, px = 0, py = 0;
  for (let i = 0; i < n; i++) { rx += src[i].x; ry += src[i].y; px += dst[i].x; py += dst[i].y; }
  rx /= n; ry /= n; px /= n; py /= n;                  // centers of both star sets
  let s00 = 0, s01 = 0, s11 = 0, c00 = 0, c01 = 0, c10 = 0, c11 = 0, dot = 0, crs = 0;
  for (let i = 0; i < n; i++) {
    const x = src[i].x - rx, y = src[i].y - ry, X = dst[i].x - px, Y = dst[i].y - py;
    s00 += x * x; s01 += x * y; s11 += y * y;          // spread of the resting stars
    c00 += X * x; c01 += X * y; c10 += Y * x; c11 += Y * y;
    dot += x * X + y * Y; crs += x * Y - y * X;        // for the rotate-and-scale fit
  }
  const norm = s00 + s11;
  if (norm < 1e-9) return null;
  const sa = dot / norm, sb = crs / norm;              // best rotate-and-scale: [sa -sb; sb sa]
  const lam = 0.25 * norm / 2;                         // how strongly to prefer it
  // L = (C + lam·Sim) · (S + lam·I)^-1
  const m00 = s00 + lam, m01 = s01, m11 = s11 + lam;
  const det = m00 * m11 - m01 * m01;
  const i00 = m11 / det, i01 = -m01 / det, i11 = m00 / det;
  const k00 = c00 + lam * sa, k01 = c01 - lam * sb, k10 = c10 + lam * sb, k11 = c11 + lam * sa;
  const a = k00 * i00 + k01 * i01, c = k00 * i01 + k01 * i11;
  const b = k10 * i00 + k11 * i01, d = k10 * i01 + k11 * i11;
  return { a, b, c, d, e: px - (a * rx + c * ry), f: py - (b * rx + d * ry) };
}

// tint: null in sky mode, or a color during battle (white when hit)
function drawFigure(c, pts, alpha, tint, tintAmount) {
  const fig = FIGURES[c.id];
  if (!showArt || !fig || !fig.img.complete || !fig.img.naturalWidth) return false;
  const m = fitAffine(c.stars, pts);
  if (!m) return true;
  // picture pixel -> star units: u = (px - cx) / s, then units -> screen with m
  const k = 1 / fig.s;
  const T = [m.a * k, m.b * k, m.c * k, m.d * k,
             m.e - (m.a * fig.cx + m.c * fig.cy) * k, m.f - (m.b * fig.cx + m.d * fig.cy) * k];

  if (!tint) {                              // sky mode: draw straight onto the sky
    ctx.save();
    ctx.globalAlpha = alpha * ART_OPACITY;
    ctx.transform(...T);
    ctx.drawImage(fig.img, 0, 0);
    ctx.restore();
    return true;
  }

  // Battle: paint on the hidden canvas, wash it with the fighter's color, then copy it over
  const corners = [[0, 0], [fig.w, 0], [0, fig.h], [fig.w, fig.h]]
    .map(([x, y]) => ({ x: T[0] * x + T[2] * y + T[4], y: T[1] * x + T[3] * y + T[5] }));
  const x0 = Math.max(0, Math.min(...corners.map(p => p.x)) - 2), x1 = Math.min(W, Math.max(...corners.map(p => p.x)) + 2);
  const y0 = Math.max(0, Math.min(...corners.map(p => p.y)) - 2), y1 = Math.min(H, Math.max(...corners.map(p => p.y)) + 2);
  if (x1 <= x0 || y1 <= y0) return true;
  actx.clearRect(x0, y0, x1 - x0, y1 - y0);
  actx.save();
  actx.transform(...T);
  actx.drawImage(fig.img, 0, 0);
  actx.restore();
  actx.globalCompositeOperation = 'source-atop';
  actx.globalAlpha = tintAmount;
  actx.fillStyle = tint;
  actx.fillRect(x0, y0, x1 - x0, y1 - y0);
  actx.globalAlpha = 1;
  actx.globalCompositeOperation = 'source-over';
  const dpr = artCanvas.width / W;
  ctx.save();
  ctx.globalAlpha = alpha * ART_OPACITY;
  ctx.drawImage(artCanvas, x0 * dpr, y0 * dpr, (x1 - x0) * dpr, (y1 - y0) * dpr, x0, y0, x1 - x0, y1 - y0);
  ctx.restore();
  return true;
}

// =====================================================================
//  DRAWING
// =====================================================================

// Brighter stars (lower mag) get bigger dots.
function starRadius(mag) {
  return { 1: 4, 2: 3, 3: 2.2 }[mag] || 2;
}

function drawBackground() {
  // Night-sky gradient: deep blue at the top, a faint glow at the horizon.
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#060a1f');
  g.addColorStop(0.75, '#0d1640');
  g.addColorStop(1, '#2a2350');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // In battle the sky gets a faint red tint
  if (battle.blend > 0.01) {
    ctx.fillStyle = `rgba(90, 10, 60, ${0.25 * battle.blend})`;
    ctx.fillRect(0, 0, W, H);
  }
}

function drawHorizon() {
  // Simple hill silhouette at the bottom, like Stellarium's landscape.
  ctx.fillStyle = '#04060f';
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(0, H * 0.94);
  ctx.quadraticCurveTo(W * 0.25, H * 0.90, W * 0.5, H * 0.95);
  ctx.quadraticCurveTo(W * 0.75, H * 0.99, W, H * 0.93);
  ctx.lineTo(W, H);
  ctx.closePath();
  ctx.fill();
}

function drawBackgroundStars(time) {
  for (const s of BG_STARS) {
    // Twinkle: brightness goes up and down on a sine wave.
    ctx.globalAlpha = reduceMotion ? 0.8 : 0.55 + 0.45 * Math.sin(time * 0.001 * s.speed + s.phase);
    ctx.fillStyle = '#dfe6ff';
    ctx.beginPath();
    ctx.arc(s.x * W, s.y * H, s.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawConstellation(c, time) {
  const L = layoutOf(c);
  if (L.alpha <= 0.01) { c.screenPts = []; return; }

  const fighting = battle.active && fighters[c.id];
  const off = fighting ? battleOffset(c, time) : { dx: 0, dy: 0, rot: 0, alpha: 1, flash: 0, ko: 0 };
  const { pose, caption, draw } = getPose(c, time);

  const cx = L.x + off.dx, cy = L.y + off.dy, size = unit * L.scale;
  const origin = { x: 0, y: 0 };
  const pts = pose.map(p => {
    const r = rotate(p, off.rot, origin);
    return { x: cx + r.x * size, y: cy + r.y * size };
  });
  c.screenPts = pts;   // remember where the stars are this frame (used for tapping)
  c.cx = cx; c.cy = cy;

  const alpha = L.alpha * off.alpha;
  if (alpha <= 0.01) return;
  ctx.globalAlpha = alpha;

  // Falling-star trail behind a knocked-out fighter
  if (off.ko > 0) {
    const trail = ctx.createLinearGradient(cx, cy - off.dy * 0.6, cx, cy);
    trail.addColorStop(0, FIGHTERS[c.id].color + '00');
    trail.addColorStop(1, FIGHTERS[c.id].color);
    ctx.strokeStyle = trail;
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(cx, cy - off.dy * 0.6);
    ctx.lineTo(cx, cy);
    ctx.stroke();
  }

  // 0. The mythological figure, behind the lines and stars
  //    Sky mode: pale silver like Stellarium's art. Battle: the fighter's color (white when hit).
  //    Sky mode: silver. Battle: washed with the fighter's color (white when hit).
  const tint = !fighting ? null : off.flash > 0 ? '#ffffff' : FIGHTERS[c.id].color;
  drawFigure(c, pts, alpha, tint, off.flash > 0 ? 0.75 : 0.5);

  // 1. Lines between stars (fighters glow in their own color, white when hit)
  if (fighting) {
    ctx.strokeStyle = off.flash > 0 ? '#ffffff' : FIGHTERS[c.id].color;
    ctx.shadowColor = off.flash > 0 ? '#ff3b3b' : FIGHTERS[c.id].color;
    ctx.shadowBlur = off.flash > 0 ? 20 : 8;
    ctx.lineWidth = 2;
  } else if (rave.on) {                    // rave: rainbow lines that cycle colour
    ctx.strokeStyle = `hsl(${(time / 6 + c.id.length * 45) % 360}, 100%, 65%)`;
    ctx.shadowColor = ctx.strokeStyle;
    ctx.shadowBlur = 12;
    ctx.lineWidth = 2.5;
  } else {
    ctx.strokeStyle = 'rgba(120, 170, 255, 0.55)';
    ctx.lineWidth = 1.5;
  }
  ctx.beginPath();
  for (const [a, b] of c.lines) {
    ctx.moveTo(pts[a].x, pts[a].y);
    ctx.lineTo(pts[b].x, pts[b].y);
  }
  ctx.stroke();
  ctx.shadowBlur = 0;

  // 2. Stars with a soft glow (red giants Antares and Betelgeuse glow orange)
  c.stars.forEach((s, i) => {
    const r = starRadius(s.mag) * L.scale * (1 + ravePulse(time) * 0.8); // stars flash in rave mode
    const red = s.name === 'Antares' || s.name === 'Betelgeuse';
    ctx.shadowColor = red ? '#ff8a5c' : '#bcd4ff';
    ctx.shadowBlur = r * 4;
    ctx.fillStyle = red ? '#ffb38a' : '#ffffff';
    ctx.beginPath();
    ctx.arc(pts[i].x, pts[i].y, r, 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.shadowBlur = 0;

  if (draw) draw(pts, L.scale);   // extra drawing (e.g. Ursa Major's Zzz)

  // 3. Text: fighters get a name + health bar; everyone else gets a label + caption
  const rest = c.stars.map(s => ({ x: cx + s.x * size, y: cy + s.y * size }));
  const top = Math.min(...rest.map(p => p.y));
  const lowest = Math.max(...rest.map(p => p.y));
  ctx.textAlign = 'center';

  if (fighting) {
    drawHealthBar(c, cx, top - unit * 0.35);
  } else {
    ctx.fillStyle = 'rgba(150, 190, 255, 0.85)';
    ctx.font = `${Math.max(10, unit * 0.18 * L.scale)}px "JetBrains Mono", ui-monospace, monospace`;
    ctx.fillText(c.name, cx, lowest + unit * 0.35 * L.scale);
    if (caption && L.scale > 0.7) {          // skip captions when shrunk into a corner
      ctx.fillStyle = '#ff5fb8';
      ctx.font = `800 ${Math.max(10, unit * 0.2 * L.scale)}px "Bricolage Grotesque", system-ui, sans-serif`;
      ctx.fillText(caption, cx, top - unit * 0.25 * L.scale);
    }
  }
  ctx.globalAlpha = 1;
}

// Name and a small health bar floating above a fighter
function drawHealthBar(c, x, y) {
  const st = fighters[c.id];
  const w = Math.max(64, unit * 1.5), h = 5;

  ctx.fillStyle = 'rgba(255, 255, 255, 0.15)';
  ctx.fillRect(x - w / 2, y, w, h);
  ctx.fillStyle = st.hp > 50 ? FIGHTERS[c.id].color : st.hp > 25 ? '#ffd36b' : '#ff4d4d';
  ctx.fillRect(x - w / 2, y, w * st.shownHp / 100, h);

  ctx.font = `800 ${Math.max(11, unit * 0.2)}px "Bricolage Grotesque", sans-serif`;
  ctx.fillStyle = st.winner ? '#ff5fb8' : '#e8edff';
  ctx.fillText(st.winner ? `${c.name.toUpperCase()} WINS` : c.name.toUpperCase(), x, y - 6);
}

// POW! / WHIFF! bursts on whoever just got attacked
function drawBursts(now) {
  for (const fight of battle.fights) {
    const b = fight.burst;
    if (!b) continue;
    const age = (now - b.start) / 650;
    if (age >= 1) continue;
    const target = byId[b.id];
    ctx.save();
    ctx.translate(target.cx, target.cy - unit * 0.3);
    ctx.globalAlpha = 1 - age;
    ctx.strokeStyle = '#ffd36b';
    ctx.lineWidth = 2.5;
    for (let k = 0; k < 10; k++) {            // starburst rays
      const a = k * Math.PI / 5;
      const r1 = unit * 0.3, r2 = unit * (0.55 + age * 0.35);
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * r1, Math.sin(a) * r1);
      ctx.lineTo(Math.cos(a) * r2, Math.sin(a) * r2);
      ctx.stroke();
    }
    ctx.rotate(-0.15);
    ctx.textAlign = 'center';
    ctx.font = `800 ${unit * 0.42 * (1 + (1 - age) * 0.3)}px "Bricolage Grotesque", sans-serif`;
    ctx.lineWidth = 5;
    ctx.strokeStyle = '#1a0612';
    ctx.strokeText(b.word, 0, 0);
    ctx.fillStyle = '#ffd36b';
    ctx.fillText(b.word, 0, 0);
    ctx.restore();
  }
}

// Split text into lines that fit a width
function wrapText(text, maxWidth) {
  const words = text.split(' ');
  const lines = [];
  let line = '';
  for (const w of words) {
    const test = line ? line + ' ' + w : w;
    if (ctx.measureText(test).width > maxWidth && line) { lines.push(line); line = w; }
    else line = test;
  }
  if (line) lines.push(line);
  return lines;
}

// Big "FIGHT!" at the start, and the announcer box at the bottom
function drawBattleHUD(now) {
  ctx.textAlign = 'center';

  if (battle.phase === 'intro') {
    const e = now - battle.phaseStart;
    const pop = 1 + Math.max(0, 1 - (e % 1000) / 250) * 0.3;
    ctx.save();
    ctx.translate(W / 2, H * 0.47);
    ctx.scale(pop, pop);
    ctx.font = `800 ${Math.min(80, W * 0.14)}px "Bricolage Grotesque", sans-serif`;
    ctx.lineWidth = 8;
    ctx.strokeStyle = '#1a0612';
    const word = e < 1000 ? 'READY?' : 'FIGHT!';
    ctx.strokeText(word, 0, 0);
    ctx.fillStyle = '#ff5fb8';
    ctx.fillText(word, 0, 0);
    ctx.restore();
  }

  // Announcer commentary at the bottom
  const maxW = Math.min(W - 32, 680);
  const size = Math.min(19, Math.max(14, W * 0.02));
  ctx.font = `700 ${size}px "Bricolage Grotesque", sans-serif`;
  const lines = wrapText(battle.line, maxW);
  const lineH = size * 1.3;
  const bottom = H - toolbarH - 44;           // leave room for the buttons
  const firstY = bottom - (lines.length - 1) * lineH;
  ctx.fillStyle = 'rgba(10, 6, 24, 0.75)';
  ctx.fillRect(W / 2 - maxW / 2 - 12, firstY - size - 26, maxW + 24, lines.length * lineH + 36);
  ctx.fillStyle = '#ff5fb8';
  ctx.font = '11px "JetBrains Mono", monospace';
  ctx.fillText('ANNOUNCER', W / 2, firstY - size - 8);
  ctx.fillStyle = '#e8edff';
  ctx.font = `700 ${size}px "Bricolage Grotesque", sans-serif`;
  lines.forEach((l, i) => ctx.fillText(l, W / 2, firstY + i * lineH));
}

// ---------- Obituary page (shown when all four fights are over) ----------
const obitCard = document.getElementById('obit');

function showObituaries() {
  const list = document.getElementById('obit-list');
  list.textContent = '';
  for (const { loser, winner } of battle.losers) {
    const entry = document.createElement('article');
    entry.className = 'obit-entry';
    const name = document.createElement('h2');
    name.textContent = byId[loser].name;
    const years = document.createElement('p');
    years.className = 'obit-years';
    years.textContent = OBITS[loser].years;
    const text = document.createElement('p');
    text.className = 'obit-text';
    text.textContent = OBITS[loser].text;
    const cause = document.createElement('p');
    cause.className = 'obit-cause';
    cause.textContent = `Cause of death: ${byId[winner].name}. Also hubris.`;
    entry.append(name, years, text, cause);
    list.append(entry);
  }
  obitCard.hidden = false;
  obitCard.scrollTop = 0;
}

document.getElementById('obit-rematch').addEventListener('click', startBattle);
document.getElementById('obit-leave').addEventListener('click', stopBattle);

// ---------- Figures button: show/hide the mythological artwork ----------
const artBtn = document.getElementById('btn-art');
artBtn.addEventListener('click', () => {
  showArt = !showArt;
  artBtn.setAttribute('aria-pressed', String(showArt));
  artBtn.textContent = showArt ? 'Figures on' : 'Figures off';
});

// =====================================================================
//  SOUND & MUSIC
//  Everything is made live in the browser with the Web Audio API, so there are no sound files:
//   - dramatic orchestral-style music: strings, choir, brass and timpani,
//     slow and mysterious in the sky, fast and epic in battle and rave mode
//   - sound effects for the battle (punches, whooshes, the bell, falling stars)
//  Sound starts off; browsers only allow audio after the viewer taps a button.
// =====================================================================

let soundOn = false;
let audio = null;                       // the Web Audio "mixing desk", created on first use
let fxBus = null, musicBus = null;      // volume controls for effects and for music

// ---------- Mixing desk ----------
function setupAudio() {
  audio = new (window.AudioContext || window.webkitAudioContext)();
  const comp = audio.createDynamicsCompressor();     // keeps loud moments from distorting
  comp.connect(audio.destination);
  fxBus = audio.createGain(); fxBus.gain.value = 0.9; fxBus.connect(comp);
  musicBus = audio.createGain(); musicBus.gain.value = 0; musicBus.connect(comp);
}

const midi = n => 440 * Math.pow(2, (n - 69) / 12);   // note number -> frequency

let noiseBuf = null;
function noiseSource() {
  if (!noiseBuf) {
    noiseBuf = audio.createBuffer(1, audio.sampleRate * 2, audio.sampleRate);
    const d = noiseBuf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
  }
  const s = audio.createBufferSource();
  s.buffer = noiseBuf;
  return s;
}

// A note: an oscillator through a filter with a volume envelope
function note({ freq, freq2, t, dur, type = 'sawtooth', vol = 0.1, attack = 0.01, release = 0.1,
                filter = 'lowpass', cutoff = 2000, cutoff2, q = 0.7, out = fxBus, detune = 0 }) {
  const o = audio.createOscillator(), f = audio.createBiquadFilter(), g = audio.createGain();
  o.type = type;
  o.detune.value = detune;
  o.frequency.setValueAtTime(freq, t);
  if (freq2) o.frequency.exponentialRampToValueAtTime(freq2, t + dur);
  f.type = filter; f.Q.value = q;
  f.frequency.setValueAtTime(cutoff, t);
  if (cutoff2) f.frequency.exponentialRampToValueAtTime(cutoff2, t + dur);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(vol, t + attack);
  g.gain.setValueAtTime(vol, t + Math.max(attack, dur - release));
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(f).connect(g).connect(out);
  o.start(t); o.stop(t + dur + 0.05);
}

// A burst of filtered noise (hits, whooshes, breaths, cymbals)
function hiss({ t, dur, vol = 0.2, filter = 'bandpass', cutoff = 1500, cutoff2, q = 1, attack = 0.005, out = fxBus }) {
  const s = noiseSource(), f = audio.createBiquadFilter(), g = audio.createGain();
  f.type = filter; f.Q.value = q;
  f.frequency.setValueAtTime(cutoff, t);
  if (cutoff2) f.frequency.exponentialRampToValueAtTime(cutoff2, t + dur);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(vol, t + attack);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  s.connect(f).connect(g).connect(out);
  s.start(t, Math.random()); s.stop(t + dur + 0.05);
}

// ---------- Sound effects ----------
function sfx(name) {
  if (!soundOn || !audio) return;
  const t = audio.currentTime + 0.01;
  if (name === 'punch') { note({ freq: 160, freq2: 45, t, dur: 0.2, type: 'sine', vol: 0.6 }); hiss({ t, dur: 0.08, vol: 0.35, cutoff: 1800, cutoff2: 500 }); }
  if (name === 'crit')  { note({ freq: 200, freq2: 40, t, dur: 0.4, type: 'square', vol: 0.2, cutoff: 800 }); hiss({ t, dur: 0.18, vol: 0.4, cutoff: 2500, cutoff2: 400 });
                          note({ freq: 1200, t: t + 0.04, dur: 0.6, type: 'triangle', vol: 0.12 }); }
  if (name === 'whiff') { hiss({ t, dur: 0.28, vol: 0.25, cutoff: 400, cutoff2: 3000 }); }
  if (name === 'fall')  { note({ freq: 1400, freq2: 110, t, dur: 1.3, type: 'triangle', vol: 0.22, cutoff: 5000 }); } // slide whistle
  if (name === 'bell')  { [0, 0.35].forEach(d => note({ freq: 880, t: t + d, dur: 0.7, type: 'triangle', vol: 0.3, cutoff: 6000 })); }
  if (name === 'airhorn') {                                   // BWAAP BWAAP BWAAAAP
    [0, 0.22, 0.44].forEach((d, i) => [0, 4, 7].forEach(st => note({ freq: midi(70 + st), t: t + d, dur: i < 2 ? 0.16 : 0.5,
      type: 'sawtooth', vol: 0.08, cutoff: 2600, q: 2 })));
  }
  if (name === 'pop')   { note({ freq: 500, freq2: 900, t, dur: 0.09, type: 'sine', vol: 0.15 }); }
}

// ---------- Dramatic music ----------
// D minor, four chords, one per bar: Dm - B♭ - Gm - A (the A major chord is the "dun dun DUN").
// Sky: slow (72 bpm), choir and strings, timpani on each new chord, little sparkles on top.
// Battle and rave: fast (138 bpm), driving string ostinato, brass stabs, timpani on every beat and rolls.
const PROGRESSION = [[50, 53, 57], [46, 50, 53], [43, 46, 50], [45, 49, 52]];
const music = { step: 0, nextTime: 0, timer: null };

function startMusic() {
  music.nextTime = audio.currentTime + 0.1;
  music.step = 0;
  clearInterval(music.timer);
  music.timer = setInterval(scheduleMusic, 50);   // look ahead and book notes just before they're due
}

function stopMusic() {
  clearInterval(music.timer);
  music.timer = null;
  if (musicBus) musicBus.gain.setTargetAtTime(0, audio.currentTime, 0.2);
}

function scheduleMusic() {
  const fight = battle.active || rave.on;
  const eighth = 60 / (fight ? 138 : 72) / 2;     // length of an eighth note in seconds
  while (music.nextTime < audio.currentTime + 0.3) {
    playStep(music.step, music.nextTime, fight, eighth);
    music.nextTime += eighth;
    music.step++;
  }
  const level = fight ? 0.38 : 0.32;
  musicBus.gain.setTargetAtTime(level, audio.currentTime, 0.15);
}

function playStep(step, t, fight, eighth) {
  const pos = step % 8, bar = Math.floor(step / 8), chord = PROGRESSION[bar % 4];
  const barLen = eighth * 8, out = musicBus;

  if (pos === 0) {
    // Strings pad: two slightly out-of-tune saws per note sound like a section of players
    for (const n of chord) for (const d of [-7, 7]) {
      note({ freq: midi(n), t, dur: barLen, vol: 0.035, attack: fight ? 0.05 : 0.8, release: 0.5,
             cutoff: fight ? 1600 : 900, detune: d, out });
    }
    // Choir: an "aah" an octave up
    for (const n of chord) {
      const o = audio.createOscillator(), g = audio.createGain();
      o.type = 'sawtooth'; o.frequency.value = midi(n + 12);
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(fight ? 0.05 : 0.07, t + (fight ? 0.1 : 1.0));
      g.gain.exponentialRampToValueAtTime(0.0001, t + barLen);
      for (const fq of [750, 1150]) {
        const bp = audio.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = fq; bp.Q.value = 6;
        o.connect(bp).connect(g);
      }
      g.connect(out); o.start(t); o.stop(t + barLen + 0.05);
    }
    // Timpani on every new chord
    note({ freq: midi(chord[0] - 12), freq2: midi(chord[0] - 13), t, dur: 0.9, type: 'sine', vol: fight ? 0.55 : 0.4, out });
    hiss({ t, dur: 0.12, vol: 0.15, filter: 'lowpass', cutoff: 400, out });
    // Cymbal swell into the start of each loop
    if (bar % 4 === 3) hiss({ t, dur: barLen, vol: 0.12, filter: 'highpass', cutoff: 5000, attack: barLen * 0.95, out });
  }

  if (!fight) {
    // Sky: slow bass, and a twinkling arpeggio
    if (pos === 0) note({ freq: midi(chord[0] - 24), t, dur: barLen, type: 'triangle', vol: 0.25, attack: 0.3, cutoff: 400, out });
    if (pos === 3 || pos === 5 || pos === 7) {
      note({ freq: midi(chord[(pos - 3) / 2] + 24), t, dur: 0.6, type: 'triangle', vol: 0.05, cutoff: 6000, out });
    }
    if (pos === 4) note({ freq: midi(chord[0] - 12), freq2: midi(chord[0] - 13), t, dur: 0.6, type: 'sine', vol: 0.18, out });
    return;
  }

  // Battle: driving eighth-note strings and bass
  note({ freq: midi((pos % 2 ? chord[2] : chord[0]) + 12), t, dur: eighth * 0.9, vol: 0.07, cutoff: 2400, release: 0.05, out });
  note({ freq: midi(chord[0] - 24), t, dur: eighth * 0.9, vol: 0.18, cutoff: 350, release: 0.05, out });
  // Timpani on beats 1–4, with a roll at the end of every 4 bars
  if (pos % 2 === 0) note({ freq: midi(chord[0] - 12), freq2: midi(chord[0] - 13), t, dur: 0.5, type: 'sine', vol: 0.35, out });
  if (bar % 4 === 3 && pos >= 4) {
    for (let r = 0; r < 4; r++) note({ freq: midi(chord[0] - 12), t: t + r * eighth / 4, dur: 0.2, type: 'sine', vol: 0.2 + r * 0.04, out });
  }
  // Brass stab every other bar: the filter opens up like a horn blast
  if (pos === 0 && bar % 2 === 0) {
    for (const n of chord) note({ freq: midi(n + 12), t, dur: 0.7, vol: 0.06, attack: 0.03, cutoff: 500, cutoff2: 2800, q: 2, out });
  }
}

// ---------- Battle sound effects ----------
function reactDodge() { sfx('whiff'); }
function reactHit(aId, dId, crit) { sfx(crit ? 'crit' : 'punch'); }
function reactKO() { sfx('fall'); }

// ---------- Sound button ----------
const soundBtn = document.getElementById('btn-sound');
soundBtn.addEventListener('click', () => {
  soundOn = !soundOn;
  soundBtn.setAttribute('aria-pressed', String(soundOn));
  soundBtn.textContent = soundOn ? 'Sound on' : 'Sound off';
  if (soundOn) {
    try {
      if (!audio) setupAudio();
      audio.resume();
      startMusic();
    } catch (e) { audio = null; }                              // no Web Audio: voices only
    sfx('pop');
  } else {
    stopMusic();
  }
});

// =====================================================================
//  EXTRAS (STEP 5): rave mode, real mode, screenshot sharing
// =====================================================================

// ---------- Rave mode: rainbow lasers, flashing stars, everyone dances double speed ----------
const rave = { on: false, until: 0, start: 0 };

function setRave(on, now, ms = 0) {
  if (on && real.on) setReal(false, now);
  rave.on = on;
  rave.until = ms ? now + ms : 0;          // 0 = stays on until turned off
  rave.start = now;
  speed = on ? BASE_SPEED * 1.8 : BASE_SPEED;
  raveBtn.textContent = on ? 'Stop rave' : 'Rave';
  raveBtn.setAttribute('aria-pressed', String(on));
  if (on) {
    sfx('airhorn');
  }
}

// Coloured overlay + sweeping laser beams, drawn behind the constellations
function drawRave(time) {
  if (!rave.on) return;
  const hue = (time / 12) % 360;
  ctx.fillStyle = `hsla(${hue}, 90%, 45%, 0.18)`;
  ctx.fillRect(0, 0, W, H);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';  // overlapping beams add up and glow
  ctx.lineWidth = 3;
  for (let k = 0; k < 6; k++) {
    const fromLeft = k % 2 === 0;
    const x0 = fromLeft ? 0 : W, y0 = H * 0.95;
    const angle = (fromLeft ? -1 : -2.1) + Math.sin(time / 600 + k) * 0.5;
    const len = Math.hypot(W, H);
    ctx.strokeStyle = `hsla(${(hue + k * 60) % 360}, 100%, 60%, 0.35)`;
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    ctx.lineTo(x0 + Math.cos(angle) * len, y0 + Math.sin(angle) * len);
    ctx.stroke();
  }
  ctx.restore();
}

// How much the stars pulse on the beat (0–1)
const ravePulse = time => (rave.on ? Math.pow(Math.abs(Math.sin(time / 1000 * speed * Math.PI * 2)), 4) : 0);

// Shake the phone to start a rave (devices with motion sensors)
let lastShakeAt = 0;
window.addEventListener('devicemotion', e => {
  const a = e.accelerationIncludingGravity;
  if (!a) return;
  const force = Math.hypot(a.x || 0, a.y || 0, a.z || 0);
  const now = performance.now();
  if (force > 25 && now - lastShakeAt > 1500 && !battle.active) {
    lastShakeAt = now;
    if (!rave.on) setRave(true, now, 8000);  // a shake gives an 8-second rave
  }
});

// iPhones ask permission before sharing motion data; this must happen after a tap
function askMotionPermission() {
  if (typeof DeviceMotionEvent !== 'undefined' && typeof DeviceMotionEvent.requestPermission === 'function') {
    DeviceMotionEvent.requestPermission().catch(() => {});
  }
}

const raveBtn = document.getElementById('btn-rave');
raveBtn.addEventListener('click', () => {
  askMotionPermission();
  setRave(!rave.on, performance.now());
});

// ---------- Real mode: a few seconds of calm, accurate Stellarium ----------
const REAL_MS = 6000;
const real = { on: false, until: 0, shownSecond: -1 };

function setReal(on, now) {
  real.on = on;
  real.until = now + REAL_MS;
  real.shownSecond = -1;
  realBtn.textContent = on ? 'Back to chaos' : 'Real mode';
  realBtn.setAttribute('aria-pressed', String(on));
  if (on) {
    if (rave.on) setRave(false, now);
    if (battle.active) stopBattle();
    hideInfo();
  } else {
    updateModeUI();                          // puts the normal tagline back
  }
}

const realBtn = document.getElementById('btn-real');
realBtn.addEventListener('click', () => setReal(!real.on, performance.now()));

// Runs every frame: switches modes off when their time is up, updates the countdown
function updateModes(now) {
  if (rave.on && rave.until && now > rave.until) setRave(false, now);
  if (!real.on) return;
  if (now > real.until) { setReal(false, now); return; }
  const left = Math.ceil((real.until - now) / 1000);
  if (left !== real.shownSecond) {
    real.shownSecond = left;
    document.getElementById('tagline').textContent = `Real mode · back to chaos in ${left}…`;
  }
}

// ---------- Screenshot: share it, or save it if sharing isn't available ----------
const toastEl = document.getElementById('toast');
let toastTimer = null;
function toast(text) {
  toastEl.textContent = text;
  toastEl.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { toastEl.hidden = true; }, 2600);
}

async function shareScreenshot() {
  // Copy the sky and stamp the title on it (the title is HTML, so it isn't in the canvas)
  const shot = document.createElement('canvas');
  shot.width = canvas.width;
  shot.height = canvas.height;
  const s = shot.getContext('2d');
  s.drawImage(canvas, 0, 0);
  const dpr = canvas.width / W;
  s.scale(dpr, dpr);
  s.font = '800 26px "Bricolage Grotesque", system-ui, sans-serif';
  s.fillStyle = '#e8edff';
  s.fillText('Stellarium', 16, 40);
  s.fillStyle = '#ff5fb8';
  s.fillText('Unhinged', 24 + s.measureText('Stellarium').width, 40);

  const blob = await new Promise(resolve => shot.toBlob(resolve, 'image/png'));
  if (!blob) { toast("Couldn't make the screenshot. Try again."); return; }
  const file = new File([blob], 'stellarium-unhinged.png', { type: 'image/png' });

  // Phones (and some laptops) can share straight to apps
  try {
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({ files: [file], title: 'Stellarium Unhinged', text: 'The constellations have lost it.' });
      toast('Shared!');
      return;
    }
  } catch (e) {
    if (e.name === 'AbortError') return;      // the viewer closed the share sheet
  }

  // Otherwise, download the picture
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = 'stellarium-unhinged.png';
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(link.href), 4000);
  toast('Screenshot saved as stellarium-unhinged.png');
}

document.getElementById('btn-share').addEventListener('click', () => {
  sfx('pop');
  shareScreenshot();
});

