const card = document.getElementById('info');

function showInfo(id) {
  const info = INFO[id];
  if (!info) return;
  document.getElementById('info-title').textContent = info.title;
  const stats = document.getElementById('info-stats');
  stats.textContent = '';
  for (const [label, value] of info.stats) {
    const dt = document.createElement('dt'); dt.textContent = label;
    const dd = document.createElement('dd'); dd.textContent = value;
    stats.append(dt, dd);
  }
  document.getElementById('info-fact').textContent = pick(info.facts);
  document.getElementById('info-real').textContent = 'Actual fact: ' + info.real;
  card.hidden = false;
}

function hideInfo() { card.hidden = true; }

// Find which constellation (if any) is under a tap/click
function constellationAt(x, y) {
  const reach = Math.max(28, unit * 0.45);   // finger-friendly hit area
  let best = null, bestDist = reach;
  for (const c of CONSTELLATIONS) {
    for (const p of c.screenPts || []) {
      const d = Math.hypot(p.x - x, p.y - y);
      if (d < bestDist) { bestDist = d; best = c; }
    }
  }
  return best;
}

// pointerup works for mouse clicks AND finger taps
canvas.addEventListener('pointerup', e => {
  if (battle.active) return;                 // no info cards mid-fight
  const hit = constellationAt(e.clientX, e.clientY);
  if (hit) showInfo(hit.id);
  else hideInfo();                           // tapping empty sky closes the card
});
document.getElementById('info-close').addEventListener('click', hideInfo);

// =====================================================================
//  MAIN LOOP: about 60 times a second, update and redraw everything
// =====================================================================
function loop(time) {
  battle.blend += ((battle.active ? 1 : 0) - battle.blend) * 0.05; // smooth switch between modes
  updateModes(time);
  if (battle.active) updateBattle(time);

  ctx.save();
  if (battle.shake > 0.05) {                  // screen shake on big hits
    ctx.translate((Math.random() - 0.5) * battle.shake * 8, (Math.random() - 0.5) * battle.shake * 8);
  }
  drawBackground();
  drawBackgroundStars(time);
  drawRave(time);
  CONSTELLATIONS.forEach(c => drawConstellation(c, time));
  drawHorizon();                              // drawn last so knocked-out fighters fall behind the hill
  if (battle.active) drawBursts(time);
  ctx.restore();

  if (battle.active) drawBattleHUD(time);
  requestAnimationFrame(loop);
}

// ---------- Start ----------
makeBackgroundStars(320);
resetFighters();
resize();
window.addEventListener('resize', resize);
requestAnimationFrame(loop);


